.section--dark p { color: rgba(255,255,255,0.7); }
.section--dark .section-label { color: var(--color-accent); }

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  border-radius: var(--radius-full);
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 0.9375rem;
  transition: all var(--transition-base);
  white-space: nowrap;
}
.btn--primary {
  background: var(--color-accent);
  color: var(--color-primary);
}
.btn--primary:hover { background: var(--color-accent-hover); transform: translateY(-1px); box-shadow: var(--shadow-md); }
.btn--secondary {
  background: transparent;
  color: var(--color-text);
  border: 1.5px solid var(--color-border);
}
.btn--secondary:hover { border-color: var(--color-primary); background: var(--color-bg-alt); }
.btn--dark {
  background: var(--color-primary);
  color: #fff;
}
.btn--dark:hover { background: #222; transform: translateY(-1px); }
.btn--large { padding: 18px 36px; font-size: 1rem; }
.btn i { font-size: 1.125rem; }

/* ===== NAVIGATION ===== */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border);
  transition: all var(--transition-base);
}
.nav__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 24px;
  height: 72px;
}
.nav__logo {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 1.5rem;
  color: var(--color-primary);
  display: flex;
  align-items: center;
  gap: 2px;
}
.nav__logo span { color: var(--color-accent); background: var(--color-primary); padding: 0 4px; border-radius: 4px; margin-left: 2px; }
.nav__links {
  display: flex;
  align-items: center;
  gap: 32px;
}
.nav__link {
  font-family: var(--font-heading);
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-text);
  transition: color var(--transition-fast);
  position: relative;
}
.nav__link:hover { color: var(--color-burgundy); }
.nav__link::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--color-accent);
  transition: width var(--transition-base);
}
.nav__link:hover::after { width: 100%; }
.nav__cta { margin-left: 8px; }
.nav__mobile-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 4px;
}
.nav__mobile-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-primary);
  border-radius: 2px;
  transition: all var(--transition-base);
}
.nav__mobile-toggle.active span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.nav__mobile-toggle.active span:nth-child(2) { opacity: 0; }
.nav__mobile-toggle.active span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }
.nav__mobile-menu {
  display: none;
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  background: #fff;
  padding: 24px;
  border-bottom: 1px solid var(--color-border);
  box-shadow: var(--shadow-lg);
}
.nav__mobile-menu.active { display: block; }
.nav__mobile-menu a {
  display: block;
  padding: 12px 0;
  font-family: var(--font-heading);
  font-weight: 500;
  font-size: 1.0625rem;
  border-bottom: 1px solid var(--color-border);
}
.nav__mobile-menu .btn { margin-top: 16px; width: 100%; }

/* ===== HERO ===== */
.hero {
  padding: 140px 0 80px;
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  top: -200px;
  right: -200px;
  width: 600px;
  height: 600px;
  background: var(--color-accent);
  opacity: 0.08;
  border-radius: 50%;
  filter: blur(100px);
}
.hero__inner { position: relative; z-index: 1; }
.hero__content { text-align: center; max-width: 800px; margin: 0 auto; }
.hero__title { margin-bottom: 1.25rem; }
.hero__subtitle {
  font-size: 1.1875rem;
  color: var(--color-text-muted);
  line-height: 1.7;
  margin-bottom: 2rem;
  max-width: 620px;
  margin-left: auto;
  margin-right: auto;
}
.hero__actions { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

/* Hero Tab Switch */
.hero__tabs {
  margin-top: 3rem;
  display: flex;
  justify-content: center;
  gap: 4px;
  background: var(--color-bg-alt);
  border-radius: var(--radius-full);
  padding: 4px;
  width: fit-content;
  margin-left: auto;
  margin-right: auto;
}
.hero__tab {
  padding: 10px 24px;
  border-radius: var(--radius-full);
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 0.875rem;
  color: var(--color-text-muted);
  transition: all var(--transition-base);
}
.hero__tab.active {
  background: var(--color-primary);
  color: #fff;
}
.hero__preview {
  margin-top: 2rem;
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-xl);
  border: 1px solid var(--color-border);
  aspect-ratio: 16/9;
  position: relative;
  background: var(--color-bg-alt);
}
.hero__preview-panel {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: opacity var(--transition-slow);
  padding: 2rem;
}
.hero__preview-panel.active { opacity: 1; }
.hero__preview-mock {
  width: 100%;
  max-width: 900px;
  border-radius: var(--radius-lg);
  overflow: hidden;
}
.mock-dashboard {
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
}
.mock-dashboard__topbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 16px;
  background: var(--color-bg-alt);
  border-bottom: 1px solid var(--color-border);
}
.mock-dot { width: 10px; height: 10px; border-radius: 50%; }
.mock-dot--red { background: #FF5F57; }
.mock-dot--yellow { background: #FFBD2E; }
.mock-dot--green { background: #28CA41; }
.mock-dashboard__body { padding: 20px; display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.mock-stat-card {
  background: var(--color-bg-alt);
  border-radius: var(--radius-md);
  padding: 14px;
}
.mock-stat-card__label { font-size: 0.7rem; color: var(--color-text-light); margin-bottom: 4px; }
.mock-stat-card__value { font-family: var(--font-heading); font-weight: 700; font-size: 1.125rem; }
.mock-stat-card__change { font-size: 0.7rem; color: #16a34a; margin-top: 2px; }
.mock-student-view {
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  padding: 24px;
}
.mock-student-view__header { text-align: center; margin-bottom: 20px; }
.mock-student-view__title { font-family: var(--font-heading); font-weight: 700; font-size: 1rem; margin-bottom: 4px; }
.mock-student-view__author { font-size: 0.75rem; color: var(--color-text-muted); }
.mock-student-view__progress { margin-top: 16px; }
.mock-progress-bar { height: 6px; background: var(--color-bg-alt); border-radius: 3px; overflow: hidden; }
.mock-progress-bar__fill { height: 100%; background: var(--color-accent); border-radius: 3px; width: 65%; }
.mock-student-view__lessons { margin-top: 16px; display: flex; flex-direction: column; gap: 8px; }
.mock-lesson {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  background: var(--color-bg-alt);
  border-radius: var(--radius-sm);
  font-size: 0.8rem;
}
.mock-lesson__icon { width: 24px; height: 24px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 0.65rem; flex-shrink: 0; }
.mock-lesson__icon--done { background: var(--color-accent); color: var(--color-primary); }
.mock-lesson__icon--current { background: var(--color-burgundy); color: #fff; }
.mock-lesson__icon--locked { background: var(--color-border); color: var(--color-text-light); }

/* ===== STATS BAR ===== */
.stats-bar {
  background: var(--color-primary);
  padding: 40px 0;
}
.stats-bar__inner {
  display: flex;
  justify-content: center;
  gap: 60px;
  flex-wrap: wrap;
}
.stat-item { text-align: center; }
.stat-item__value {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: clamp(2rem, 4vw, 3rem);
  color: var(--color-accent);
  letter-spacing: -0.02em;
}
.stat-item__label {
  font-size: 0.875rem;
  color: rgba(255,255,255,0.7);
  margin-top: 4px;
}

/* ===== PRODUCTS GRID ===== */
.products__grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}
.product-card {
  padding: 40px;
  border-radius: var(--radius-xl);
  border: 1px solid var(--color-border);
  transition: all var(--transition-base);
  position: relative;
  overflow: hidden;
}
.product-card:hover {
  border-color: var(--color-accent);
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}
.product-card__icon {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-md);
  background: var(--color-bg-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 1.25rem;
  color: var(--color-burgundy);
}
.product-card__title {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.25rem;
  margin-bottom: 0.75rem;
}
.product-card__desc {
  font-size: 0.9375rem;
  color: var(--color-text-muted);
  line-height: 1.6;
  margin-bottom: 1.25rem;
}
.product-card__link {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 0.875rem;
  color: var(--color-burgundy);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: gap var(--transition-base);
}
.product-card__link:hover { gap: 10px; }

/* ===== WHY CHOOSE US TABS ===== */
.wcu__tabs {
  display: flex;
  gap: 4px;
  background: var(--color-bg-alt);
  border-radius: var(--radius-full);
  padding: 4px;
  width: fit-content;
  margin: 0 auto 3rem;
  flex-wrap: wrap;
  justify-content: center;
}
.wcu__tab {
  padding: 12px 24px;
  border-radius: var(--radius-full);
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 0.875rem;
  color: var(--color-text-muted);
  transition: all var(--transition-base);
  white-space: nowrap;
}
.wcu__tab.active {
  background: var(--color-primary);
  color: #fff;
}
.wcu__panel {
  display: none;
  animation: fadeInUp 0.4s ease;
}
.wcu__panel.active { display: grid; }
.wcu__panel-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}
.wcu__feature {
  display: flex;
  gap: 16px;
  padding: 24px;
  border-radius: var(--radius-lg);
  background: var(--color-bg-alt);
}
.wcu__feature-icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-md);
  background: var(--color-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 1.125rem;
  color: var(--color-primary);
}
.wcu__feature-title {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 1rem;
  margin-bottom: 4px;
}
.wcu__feature-desc { font-size: 0.875rem; color: var(--color-text-muted); line-height: 1.5; }

/* ===== GLOBAL SCALE ===== */
.global-scale__content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}
.global-scale__map {
  position: relative;
  border-radius: var(--radius-xl);
  overflow: hidden;
  background: var(--color-bg-alt);
  padding: 40px;
  text-align: center;
  min-height: 300px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.global-scale__map-visual {
  font-size: 8rem;
  opacity: 0.15;
  position: absolute;
}
.global-scale__map-text { position: relative; z-index: 1; }
.global-scale__map-number {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 4rem;
  color: var(--color-primary);
  letter-spacing: -0.03em;
}
.global-scale__map-label { font-size: 1rem; color: var(--color-text-muted); margin-top: 4px; }
.global-scale__details { display: flex; flex-direction: column; gap: 24px; }
.global-scale__item {
  display: flex;
  gap: 16px;
  align-items: flex-start;
}
.global-scale__item-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: var(--color-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 1.25rem;
}
.global-scale__item-title { font-family: var(--font-heading); font-weight: 700; font-size: 1.0625rem; margin-bottom: 4px; }
.global-scale__item-desc { font-size: 0.9375rem; color: var(--color-text-muted); }

/* ===== AI AUTOMATIONS ===== */
.ai-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.ai-card {
  padding: 32px;
  border-radius: var(--radius-xl);
  border: 1px solid var(--color-border);
  transition: all var(--transition-base);
}
.ai-card:hover { border-color: var(--color-accent); box-shadow: var(--shadow-md); }
.ai-card__icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: var(--color-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  margin-bottom: 1.25rem;
}
.ai-card__title { font-family: var(--font-heading); font-weight: 700; font-size: 1.125rem; margin-bottom: 0.5rem; }
.ai-card__desc { font-size: 0.9375rem; color: var(--color-text-muted); line-height: 1.6; }

/* ===== TESTIMONIALS CAROUSEL ===== */
.testimonials { overflow: hidden; }
.testimonials__track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}
.testimonials__slide {
  min-width: 100%;
  padding: 0 12px;
}
.testimonials__card {
  background: var(--color-card-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  padding: 40px;
  max-width: 700px;
  margin: 0 auto;
}
.testimonials__quote {
  font-size: 1.125rem;
  line-height: 1.7;
  color: var(--color-text);
  margin-bottom: 1.5rem;
  font-style: italic;
}
.testimonials__author { display: flex; align-items: center; gap: 12px; }
.testimonials__avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--color-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1rem;
  color: var(--color-primary);
}
.testimonials__name { font-family: var(--font-heading); font-weight: 600; font-size: 0.9375rem; }
.testimonials__role { font-size: 0.8125rem; color: var(--color-text-muted); }
.testimonials__controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 2rem;
}
.testimonials__btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 1.5px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  transition: all var(--transition-base);
  color: var(--color-text);
}
.testimonials__btn:hover { border-color: var(--color-primary); background: var(--color-bg-alt); }
.testimonials__dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 1.5rem;
}
.testimonials__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-border);
  transition: all var(--transition-base);
  cursor: pointer;
}
.testimonials__dot.active {
  background: var(--color-primary);
  width: 24px;
  border-radius: 4px;
}

/* ===== PRICING ===== */
.pricing__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}
.pricing-card {
  border-radius: var(--radius-xl);
  border: 1px solid var(--color-border);
  padding: 32px;
  transition: all var(--transition-base);
  position: relative;
}
.pricing-card:hover { box-shadow: var(--shadow-lg); }
.pricing-card--featured {
  border-color: var(--color-accent);
  background: var(--color-primary);
  color: #fff;
}
.pricing-card--featured p,
.pricing-card--featured .pricing-card__price { color: rgba(255,255,255,0.8); }
.pricing-card--featured .pricing-card__name { color: #fff; }
.pricing-card--featured .pricing-card__features li { color: rgba(255,255,255,0.8); }
.pricing-card--featured .pricing-card__features li::before { color: var(--color-accent); }
.pricing-card__badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--color-accent);
  color: var(--color-primary);
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 0.75rem;
  padding: 4px 16px;
  border-radius: var(--radius-full);
}
.pricing-card__name { font-family: var(--font-heading); font-weight: 700; font-size: 1.25rem; margin-bottom: 0.5rem; }
.pricing-card__price { font-family: var(--font-heading); font-weight: 800; font-size: 2.25rem; letter-spacing: -0.02em; margin-bottom: 4px; }
.pricing-card__price span { font-size: 0.875rem; font-weight: 500; color: var(--color-text-muted); }
.pricing-card__fee { font-size: 0.8125rem; color: var(--color-text-muted); margin-bottom: 1.5rem; }
.pricing-card--featured .pricing-card__fee { color: rgba(255,255,255,0.6); }
.pricing-card__features { margin-bottom: 1.5rem; }
.pricing-card__features li {
  font-size: 0.875rem;
  padding: 6px 0;
  padding-left: 20px;
  position: relative;
  color: var(--color-text-muted);
}
.pricing-card__features li::before {
  content: '\2713';
  position: absolute;
  left: 0;
  color: var(--color-burgundy);
  font-weight: 700;
}

/* ===== INTEGRATIONS ===== */
.integrations__grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
}
.integration-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 24px 16px;
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-border);
  transition: all var(--transition-base);
}
.integration-item:hover { border-color: var(--color-accent); box-shadow: var(--shadow-sm); }
.integration-item__icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  background: var(--color-bg-alt);
}
.integration-item__name { font-size: 0.8125rem; font-weight: 500; color: var(--color-text-muted); text-align: center; }

/* ===== FAQ ACCORDION ===== */
.faq__list { max-width: 760px; margin: 0 auto; }
.faq-item {
  border-bottom: 1px solid var(--color-border);
}
.faq-item__question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 0;
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 1.0625rem;
  color: var(--color-text);
  text-align: left;
  transition: color var(--transition-fast);
}
.faq-item__question:hover { color: var(--color-burgundy); }
.faq-item__icon {
  font-size: 1.25rem;
  transition: transform var(--transition-base);
  flex-shrink: 0;
  margin-left: 16px;
}
.faq-item.active .faq-item__icon { transform: rotate(45deg); }
.faq-item__answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-base), padding var(--transition-base);
}
.faq-item.active .faq-item__answer { max-height: 200px; }
.faq-item__answer p {
  padding-bottom: 20px;
  font-size: 0.9375rem;
  line-height: 1.7;
  color: var(--color-text-muted);
}

/* ===== CTA BANNER ===== */
.cta-banner {
  background: var(--color-primary);
  border-radius: var(--radius-xl);
  padding: 60px;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.cta-banner::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -10%;
  width: 400px;
  height: 400px;
  background: var(--color-accent);
  opacity: 0.1;
  border-radius: 50%;
  filter: blur(80px);
}
.cta-banner__title { color: #fff; margin-bottom: 1rem; position: relative; z-index: 1; }
.cta-banner__subtitle { color: rgba(255,255,255,0.7); margin-bottom: 2rem; font-size: 1.0625rem; position: relative; z-index: 1; }
.cta-banner__actions { position: relative; z-index: 1; display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

/* ===== FOOTER ===== */
.footer { background: var(--color-bg-dark); color: #fff; padding: 80px 0 40px; }
.footer__grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 60px;
}
.footer__brand-name {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 1.5rem;
  margin-bottom: 1rem;
}
.footer__brand-name span { color: var(--color-accent); }
.footer__brand-desc { font-size: 0.9375rem; color: rgba(255,255,255,0.6); line-height: 1.6; max-width: 280px; }
.footer__col-title {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 1.25rem;
  color: var(--color-accent);
}
.footer__col a {
  display: block;
  padding: 6px 0;
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.6);
  transition: color var(--transition-fast);
}
.footer__col a:hover { color: #fff; }
.footer__bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.4);
}

/* ===== FEATURE CARDS (Reusable) ===== */
.feature-cards { display: grid; gap: 24px; }
.feature-cards--3 { grid-template-columns: repeat(3, 1fr); }
.feature-cards--4 { grid-template-columns: repeat(4, 1fr); }
.feature-card {
  padding: 32px;
  border-radius: var(--radius-xl);
  border: 1px solid var(--color-border);
  transition: all var(--transition-base);
}
.feature-card:hover { border-color: var(--color-accent); box-shadow: var(--shadow-md); transform: translateY(-2px); }
.feature-card__icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: var(--color-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  margin-bottom: 1.25rem;
  color: var(--color-primary);
}
.feature-card__title { font-family: var(--font-heading); font-weight: 700; font-size: 1.125rem; margin-bottom: 0.5rem; }
.feature-card__desc { font-size: 0.9375rem; color: var(--color-text-muted); line-height: 1.6; }

/* ===== THREE STEPS ===== */
.steps { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; position: relative; }
.steps::before {
  content: '';
  position: absolute;
  top: 36px;
  left: calc(16.67% + 24px);
  right: calc(16.67% + 24px);
  height: 2px;
  background: var(--color-border);
}
.step-card { text-align: center; position: relative; }
.step-card__number {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: var(--color-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 1.5rem;
  color: var(--color-primary);
  margin: 0 auto 1.5rem;
  position: relative;
  z-index: 1;
}
.step-card__title { font-family: var(--font-heading); font-weight: 700; font-size: 1.125rem; margin-bottom: 0.75rem; }
.step-card__desc { font-size: 0.9375rem; color: var(--color-text-muted); line-height: 1.6; }

/* ===== TOOLS GRID ===== */
.tools-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 2px;
  background: var(--color-border);
  border-radius: var(--radius-xl);
  overflow: hidden;
}
.tools-grid__item {
  background: #fff;
  padding: 24px;
  text-align: center;
  transition: background var(--transition-base);
}
.tools-grid__item:hover { background: var(--color-bg-alt); }
.tools-grid__category {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-burgundy);
  margin-bottom: 8px;
}
.tools-grid__items { font-size: 0.8125rem; color: var(--color-text-muted); line-height: 1.8; }

/* ===== FILE TYPES ===== */
.file-types__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.file-type-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 24px;
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-border);
  transition: all var(--transition-base);
}
.file-type-card:hover { border-color: var(--color-accent); }
.file-type-card__icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-md);
  background: var(--color-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.125rem;
  flex-shrink: 0;
}
.file-type-card__name { font-family: var(--font-heading); font-weight: 600; font-size: 0.9375rem; }

/* ===== SPOTLIGHT CARDS ===== */
.spotlight-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.spotlight-card {
  border-radius: var(--radius-xl);
  border: 1px solid var(--color-border);
  overflow: hidden;
  transition: all var(--transition-base);
}
.spotlight-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-4px); }
.spotlight-card__img {
  height: 200px;
  background: var(--color-bg-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
}
.spotlight-card__body { padding: 24px; }
.spotlight-card__name { font-family: var(--font-heading); font-weight: 700; font-size: 1.125rem; margin-bottom: 0.5rem; }
.spotlight-card__desc { font-size: 0.9375rem; color: var(--color-text-muted); line-height: 1.6; }

/* ===== RESOURCES ===== */
.resources-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.resource-card {
  padding: 32px;
  border-radius: var(--radius-xl);
  border: 1px solid var(--color-border);
  transition: all var(--transition-base);
}
.resource-card:hover { border-color: var(--color-accent); box-shadow: var(--shadow-md); }
.resource-card__icon {
  font-size: 2rem;
  margin-bottom: 1rem;
}
.resource-card__title { font-family: var(--font-heading); font-weight: 700; font-size: 1.0625rem; margin-bottom: 0.5rem; }
.resource-card__desc { font-size: 0.9375rem; color: var(--color-text-muted); line-height: 1.6; }
.resource-card__link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 1rem;
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 0.875rem;
  color: var(--color-burgundy);
}

/* ===== PRODUCT DEMO ACCORDION ===== */
.product-demo { border: 1px solid var(--color-border); border-radius: var(--radius-xl); overflow: hidden; }
.product-demo__toggle {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24px 32px;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.0625rem;
  background: var(--color-bg-alt);
  transition: background var(--transition-fast);
}
.product-demo__toggle:hover { background: #efefed; }
.product-demo__toggle i { transition: transform var(--transition-base); }
.product-demo.active .product-demo__toggle i { transform: rotate(180deg); }
.product-demo__content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease;
}
.product-demo.active .product-demo__content { max-height: 600px; }
.product-demo__inner { padding: 32px; }

/* ===== MEMBERSHIP MANAGEMENT ===== */
.mgmt-features { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.mgmt-card {
  text-align: center;
  padding: 40px 32px;
  border-radius: var(--radius-xl);
  border: 1px solid var(--color-border);
  transition: all var(--transition-base);
}
.mgmt-card:hover { border-color: var(--color-accent); box-shadow: var(--shadow-md); }
.mgmt-card__icon {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: var(--color-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin: 0 auto 1.25rem;
}
.mgmt-card__stat {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 2rem;
  margin-bottom: 0.5rem;
  color: var(--color-burgundy);
}
.mgmt-card__title { font-family: var(--font-heading); font-weight: 700; font-size: 1.125rem; margin-bottom: 0.5rem; }
.mgmt-card__desc { font-size: 0.9375rem; color: var(--color-text-muted); line-height: 1.6; }

/* ===== SOCIAL PROOF ===== */
.social-proof__logos {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 48px;
  flex-wrap: wrap;
  opacity: 0.5;
}
.social-proof__logo {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.25rem;
  color: var(--color-text-muted);
  transition: opacity var(--transition-base);
}
.social-proof__logo:hover { opacity: 1; }

/* ===== VALUE PROPOSITION CARDS ===== */
.value-props { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.value-prop-card {
  padding: 40px 32px;
  border-radius: var(--radius-xl);
  border: 1px solid var(--color-border);
  text-align: center;
  transition: all var(--transition-base);
}
.value-prop-card:hover { border-color: var(--color-accent); box-shadow: var(--shadow-md); transform: translateY(-2px); }
.value-prop-card__icon {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-md);
  background: var(--color-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin: 0 auto 1.25rem;
}
.value-prop-card__title { font-family: var(--font-heading); font-weight: 700; font-size: 1.125rem; margin-bottom: 0.5rem; }
.value-prop-card__desc { font-size: 0.9375rem; color: var(--color-text-muted); line-height: 1.6; }

/* ===== CREATE AND SELL SECTION ===== */
.create-sell {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}
.create-sell__visual {
  border-radius: var(--radius-xl);
  background: var(--color-bg-alt);
  padding: 40px;
  min-height: 360px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.create-sell__steps { display: flex; flex-direction: column; gap: 24px; }
.create-sell__step {
  display: flex;
  gap: 16px;
  align-items: flex-start;
}
.create-sell__step-num {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--color-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 0.875rem;
  flex-shrink: 0;
}
.create-sell__step-title { font-family: var(--font-heading); font-weight: 600; font-size: 1rem; margin-bottom: 4px; }
.create-sell__step-desc { font-size: 0.9375rem; color: var(--color-text-muted); }

/* ===== BUSINESS FIT SECTION ===== */
.business-fit__grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.business-fit__card {
  padding: 32px;
  border-radius: var(--radius-xl);
  border: 1px solid var(--color-border);
  display: flex;
  gap: 20px;
  align-items: flex-start;
  transition: all var(--transition-base);
}
.business-fit__card:hover { border-color: var(--color-accent); box-shadow: var(--shadow-sm); }
.business-fit__icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: var(--color-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  flex-shrink: 0;
}
.business-fit__title { font-family: var(--font-heading); font-weight: 700; font-size: 1.0625rem; margin-bottom: 0.5rem; }
.business-fit__desc { font-size: 0.9375rem; color: var(--color-text-muted); line-height: 1.6; }

/* ===== ANIMATIONS ===== */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}
.animate-in {
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}
.animate-in.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .pricing__grid { grid-template-columns: repeat(2, 1fr); }
  .footer__grid { grid-template-columns: 1fr 1fr; }
  .global-scale__content { grid-template-columns: 1fr; }
  .create-sell { grid-template-columns: 1fr; }
  .tools-grid { grid-template-columns: repeat(3, 1fr); }
}

@media (max-width: 768px) {
  :root { --section-padding: 64px; }
  .nav__links { display: none; }
  .nav__mobile-toggle { display: flex; }
  .hero { padding: 120px 0 60px; }
  .hero__tabs { flex-direction: row; font-size: 0.8125rem; }
  .hero__tab { padding: 8px 16px; font-size: 0.8125rem; }
  .products__grid { grid-template-columns: 1fr; }
  .wcu__tabs { flex-direction: column; align-items: stretch; }
  .wcu__panel-grid { grid-template-columns: 1fr; }
  .ai-grid { grid-template-columns: 1fr; }
  .feature-cards--3 { grid-template-columns: 1fr; }
  .feature-cards--4 { grid-template-columns: 1fr; }
  .steps { grid-template-columns: 1fr; }
  .steps::before { display: none; }
  .spotlight-grid { grid-template-columns: 1fr; }
  .resources-grid { grid-template-columns: 1fr; }
  .mgmt-features { grid-template-columns: 1fr; }
  .value-props { grid-template-columns: 1fr; }
  .file-types__grid { grid-template-columns: 1fr; }
  .business-fit__grid { grid-template-columns: 1fr; }
  .integrations__grid { grid-template-columns: repeat(3, 1fr); }
  .pricing__grid { grid-template-columns: 1fr; }
  .tools-grid { grid-template-columns: repeat(2, 1fr); }
  .stats-bar__inner { gap: 32px; }
  .cta-banner { padding: 40px 24px; }
  .footer__grid { grid-template-columns: 1fr; }
  .testimonials__card { padding: 24px; }
  .mock-dashboard__body { grid-template-columns: 1fr; }
}

@media (max-width: 480px) {
  .hero__actions { flex-direction: column; align-items: center; }
  .hero__actions .btn { width: 100%; }
  .integrations__grid { grid-template-columns: repeat(2, 1fr); }
  .tools-grid { grid-template-columns: 1fr; }
}
