  .global-scale__content { grid-template-columns: 1fr; }
  .create-sell { grid-template-columns: 1fr; }
  .tools-grid { grid-template-columns: repeat(3, 1fr); }
}

@media (max-width: 768px) {
  :root { --section-padding: 64px; }
  .nav__links { display: none; }
  .nav__mobile-toggle { display: flex; }
  .hero { padding: 120px 0 60px; }
  .hero__tabs { flex-direction: row; font-size: 0.8125rem; }
  .hero__tab { padding: 8px 16px; font-size: 0.8125rem; }
  .products__grid { grid-template-columns: 1fr; }
  .wcu__tabs { flex-direction: column; align-items: stretch; }
  .wcu__panel-grid { grid-template-columns: 1fr; }
  .ai-grid { grid-template-columns: 1fr; }
  .feature-cards--3 { grid-template-columns: 1fr; }
  .feature-cards--4 { grid-template-columns: 1fr; }
  .steps { grid-template-columns: 1fr; }
  .steps::before { display: none; }
  .spotlight-grid { grid-template-columns: 1fr; }
  .resources-grid { grid-template-columns: 1fr; }
  .mgmt-features { grid-template-columns: 1fr; }
  .value-props { grid-template-columns: 1fr; }
  .file-types__grid { grid-template-columns: 1fr; }
  .business-fit__grid { grid-template-columns: 1fr; }
  .integrations__grid { grid-template-columns: repeat(3, 1fr); }
  .pricing__grid { grid-template-columns: 1fr; }
  .tools-grid { grid-template-columns: repeat(2, 1fr); }
  .stats-bar__inner { gap: 32px; }
  .cta-banner { padding: 40px 24px; }
  .footer__grid { grid-template-columns: 1fr; }
